response.glsl:
#version 300 es
precision highp float;
precision highp int;
flat out highp uvec2 wv_so_0;
smooth out vec4 vso_g0;
uniform uvec4 vsconst0[2];
layout(std140) uniform VirglBlock {
vec4 clipp[8];
uint stipple_pattern[32];
float winsys_adjust_y;
float alpha_ref_val;
bool clip_plane_enabled;
int drawid_base;
};
uniform vec2 wv_point_size;
void main() {
bool flow_condition;
uvec4 o0;
uvec4 o31 = uvec4(0u);
{
uvec4 a = (vsconst0[0]).xyzw;
uvec4 r = a;
o0.xyzw = r.xyzw;
}
{
uvec4 a = (vsconst0[1]).xyzw;
uvec4 r = a;
o31.xy = r.xy;
}
wv_so_0 = o31.xy;
gl_Position = uintBitsToFloat(o0);
vso_g0 = uintBitsToFloat(o31);
gl_Position.y *= winsys_adjust_y;
gl_PointSize = wv_point_size.y > 0.5 ? 1.0 : wv_point_size.x;
}

